import{_ as u,a0 as i,w as o,s as p,ao as l,I as r,x as a,a1 as n,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"在Ubuntu 14.04 中修复无法清空回收站的问题 | LCTT x X-CMD","titleTemplate":false,"description":"在Ubuntu 14.04 中修复无法清空回收站的问题 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Ubuntu 14.04 中修复无法清空回收站的问题 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Ubuntu 14.04 中修复无法清空回收站的问题 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150209 Fix Cannot Empty Trash In Ubuntu 14.04 [Quick Tip]","title":"在Ubuntu 14.04 中修复无法清空回收站的问题","tag":"201504","desc":""},"relativePath":"201504/20150209 Fix Cannot Empty Trash In Ubuntu 14.04 [Quick Tip].md","filePath":"[post].md"}'),d={name:"201504/20150209 Fix Cannot Empty Trash In Ubuntu 14.04 [Quick Tip].md"};function m(f,t,T,b,h,x){const e=i("Link");return o(),p("div",null,[t[13]||(t[13]=l(`<h1 id="在ubuntu-14-04-中修复无法清空回收站的问题" tabindex="-1">在Ubuntu 14.04 中修复无法清空回收站的问题 <a class="header-anchor" href="#在ubuntu-14-04-中修复无法清空回收站的问题" aria-label="Permalink to “在Ubuntu 14.04 中修复无法清空回收站的问题”">​</a></h1><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/empty-the-trash.jpg" alt=""></p><h3 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to “问题”">​</a></h3><p><strong>我遇到了无法在Ubuntu 14.04中清空回收站的问题</strong>。我右键回收站图标并选择清空回收站，就像我一直做的那样。我看到进度条显示删除文件中过了一段时间。但是它停止了，并且Nautilus文件管理也停止了。我不得不在终端中停止了它。</p><p>但是这很痛苦因为文件还在垃圾箱中。并且我反复尝试清空后窗口都冻结了。</p><h3 id="方案" tabindex="-1">方案 <a class="header-anchor" href="#方案" aria-label="Permalink to “方案”">​</a></h3><p>老实说，我不知道什么导致了这个问题。但是我有一个解决方案如果你在Ubuntu 14.04或者14.10遇到这个问题的话。</p><p>打开终端并使用下面的命令:</p><pre><code>sudo rm -rf ~/.local/share/Trash/*
</code></pre><p>这里注意你的输入。你使用超级管理员权限来运行删除命令。我相信你不会删除其他文件或者目录。</p><p>上面的命令会删除回收站目录下的所有文件。换句话说，这是用命令清空垃圾箱。使用完上面的命令后，你会看到垃圾箱已经清空了。如果你清空了所有文件，你不应该在看到Nautilus崩溃的问题了。</p><h3 id="对你有用么" tabindex="-1">对你有用么？ <a class="header-anchor" href="#对你有用么" aria-label="Permalink to “对你有用么？”">​</a></h3><p>我希望这篇贴士对你有用，今后你也不会在Ubuntu或者其他发行版中再遇到相同的问题。如果你遇到任何问题请让我知道。</p><hr>`,14)),r("p",null,[t[1]||(t[1]=a("via: ",-1)),n(e,{href:"http://itsfoss.com/fix-empty-trash-ubuntu/"},{default:s(()=>[...t[0]||(t[0]=[a("http://itsfoss.com/fix-empty-trash-ubuntu/",-1)])]),_:1})]),r("p",null,[t[5]||(t[5]=a("作者：",-1)),n(e,{href:"http://itsfoss.com/author/abhishek/"},{default:s(()=>[...t[2]||(t[2]=[a("Abhishek",-1)])]),_:1}),t[6]||(t[6]=a(" 译者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:s(()=>[...t[3]||(t[3]=[a("geekpi",-1)])]),_:1}),t[7]||(t[7]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[4]||(t[4]=[a("wxy",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[8]||(t[8]=[a("LCTT",-1)])]),_:1}),t[11]||(t[11]=a(" 原创翻译，",-1)),n(e,{href:"http://linux.cn/"},{default:s(()=>[...t[9]||(t[9]=[a("Linux中国",-1)])]),_:1}),t[12]||(t[12]=a(" 荣誉推出",-1))])])}const g=u(d,[["render",m]]);export{_ as __pageData,g as default};
